use serde_json::{Value, Result};

pub fn solve(input: Value) -> Value {
    let mut arr: Vec<Value> = input.as_array().unwrap();
    arr.sort_by_key(|k| {
        let key = k.as_array().unwrap()[0].as_i64().unwrap();
        (key, k.as_array().unwrap()[1].as_i64().unwrap())
    });
